const root=document.getElementById('root'), E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const V=[['bizdoc','documents, tax & compliance','#18875b'],['medialy','branding, marketing & conversion','#c63645'],['subt','software, automation & workflows','#2466bf'],['iotics','smart spaces, robotics & hardware','#a0780d'],['hamzury hub','practical skills & business training','#14233b'],['iwiin','grants, partnerships & opportunities','#355c21']];
const Q=(id,label,type='text',options=[])=>({id,label,type,options});
const templates=[
{id:'general',title:'understand my business',intro:'let’s understand what you do, where you are now and the next result you want.',qs:[Q('business','what is your business name?'),Q('offer','what do you sell, and who buys it?','textarea'),Q('stage','where is the business today?','select',['idea','starting','operating','expanding']),Q('goal','what do you most want to achieve now?','textarea'),Q('challenge','what is getting in the way?','textarea'),Q('assets','what do you already have?','textarea'),Q('vision','what would you like the business to become in 1–3 years?','textarea')]},
{id:'direct',title:'i know the service i need',intro:'tell us the service and timing. we will clarify the scope before proposing work.',qs:[Q('business','what is your business name?'),Q('service','which service do you need?','textarea'),Q('existing','what is already available?','textarea'),Q('timing','when do you need it, and why?','textarea'),Q('detail','anything else we should understand?','textarea')]},
{id:'growth',title:'more customers & better conversion',intro:'help us understand the offer, enquiries and what happens before a customer buys.',qs:[Q('business','what is your business name?'),Q('offer','what do you sell, and to whom?','textarea'),Q('sales','how are sales going?','select',['few enquiries','enquiries but few sales','occasional customers','regular customers; want more']),Q('channels','where do enquiries come from?','textarea'),Q('followup','how do you follow up and close sales?','textarea'),Q('goal','what result matters most over the next three months?','textarea')]},
{id:'software',title:'software & workflow fit',intro:'start with the work you need to simplify. detailed team and technical onboarding follows an agreed scope.',qs:[Q('business','what is your business name?'),Q('industry','what kind of business do you run?'),Q('process','which repeated process is difficult today?','textarea'),Q('tools','what tools do you currently use?','textarea'),Q('solution','which route are you exploring?','select',['ready-made solution','configure an existing template','custom workflow','recommend a suitable route']),Q('goal','what should improve when this works?','textarea')]},
{id:'compliance',title:'documents & compliance support',intro:'tell us the business situation first. sensitive documents are collected securely after scope and payment approval.',qs:[Q('business','what is the business name or proposed name?'),Q('activity','what does the business do and where does it operate?','textarea'),Q('need','what document or business situation do you need help with?','textarea'),Q('existing','which business documents already exist?','textarea'),Q('timing','is there an application, bank request or deadline?','textarea')]},
{id:'training',title:'skills & programme discovery',intro:'help us recommend a suitable learning route. this form does not request sensitive identity documents.',qs:[Q('business','what name should we use for this enquiry?'),Q('route','what are you interested in?','select',['digital foundation','innovator to ceo','it / siwes / internship','junior innovator','business or team training','help me choose']),Q('skills','what can you already do?','textarea'),Q('goal','what do you want to learn or build?','textarea'),Q('availability','when are you available?','textarea')]}
];
const now=()=>new Date().toISOString(), displayDate=x=>x?new Date(x).toLocaleString('en-NG',{timeZone:'Africa/Lagos',dateStyle:'medium',timeStyle:'short'}):'not set';
let db=JSON.parse(localStorage.getItem('hh-v3')||'null')||{ventures:V.map(([name,mandate,color])=>({name,mandate,color,ceo:'to assign',target:'not set'})),forms:templates,services:offerSeed.map(s=>({...s,price:'',days:''})),leads:[{id:'HH-DEMO-001',name:'sample interior design studio',contact:'sample contact',source:'whatsapp',venture:'holding',scenario:'growth',stage:'discovery',created:now(),next:'review the discovery answers',due:'',answers:{business:'sample interior design studio',offer:'interior design and home finishing',sales:'occasional customers',channels:'social media',goal:'more customers and clearer business structure'},proposal:'your next step is to check the foundation, clarify your profile and make it easier for suitable customers to find you. start with missing essentials, then develop the next stage.',proposalVersion:null,roadmapVersion:null,selected:['b1','m1','s1'],paid:false,requirements:[],work:[],updates:[],files:[],events:[{at:now(),text:'sample enquiry captured from whatsapp'}]}]};
let route=[],activeTab='overview',filter='all',query='',formStep=0,formAnswers={},currentFormKey='',clientTier=0,toastTimer;
function save(){try{localStorage.setItem('hh-v3',JSON.stringify(db))}catch{toast('browser storage is full. remove large demo records before continuing.')}}
function toast(t){let el=document.getElementById('toast');el.textContent=t;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',4200)}
function uid(prefix){return prefix+'-'+Array.from(crypto.getRandomValues(new Uint8Array(6)),n=>n.toString(16).padStart(2,'0')).join('')}function lead(id){return db.leads.find(l=>l.id===id)}function event(l,text){l.events.unshift({at:now(),text});save()}function go(path){if(location.hash==='#'+path)render();else location.hash=path;window.scrollTo(0,0)}
function tag(v){return `<span class="vtag" style="--v:${db.ventures.find(x=>x.name===v)?.color||'#3b241a'}">${E(v)}</span>`}function pill(t){return `<span class="pill">${E(t)}</span>`}function button(t,path,cls=''){return `<button class="${cls}" onclick="go('${path}')">${t}</button>`}function link(path){return location.origin+location.pathname+'#'+path}function note(t){return `<div class="note">${t}</div>`}function title(k,t,p,actions=''){return `<div class="title"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${p}</p></div><div class="actions">${actions}</div></div>`}function footer(){return `<footer class="foot"><span>awareness / strategy / structure / systems / success</span><span>hamzury holding · your next step</span></footer>`}
function publicNav(){return `<header class="publicnav"><a href="#home"><img class="logo" src="assets/hamzury.png" alt="hamzury holding"></a><nav class="links"><a href="#home/ventures">our expertise</a><a href="#access">my project</a><a class="button secondary" href="#workspace">workspace preview</a></nav></header>`}
function demo(){return `<div class="demo">interactive experience · sample records and changes stay in this browser · no live messages, payments or secure client accounts</div>`}
const navs=[['workspace','overview'],['crm','client crm'],['forms','discovery studio'],['catalogue','service catalogue'],['venture','venture workspaces'],['queue','action queue'],['home','holding website']];
function workspace(content){return `<aside class="sidebar"><a href="#home"><img class="logo" src="assets/hamzury.png" alt="hamzury holding"></a><nav>${navs.map(([p,t])=>`<a class="${route[0]===p?'active':''}" href="#${p}">${t}</a>`).join('')}<a href="operations.html">calendar, standards & reports ↗</a></nav><div class="bottom">one client record.<br>specialist delivery.<br>clear ownership.</div></aside><main class="workspace"><header class="workhead"><span class="eyebrow" style="margin:0">holding / ${E(route[0])}</span>${pill('demonstration workspace')}</header>${content}${footer()}</main>`}
function render(){route=location.hash.slice(1).split('/');let p=route[0]||'home';let html;if(p==='home')html=home();else if(p==='form')html=discoveryView();else if(p==='client')html=clientView();else if(p==='access')html=access();else{let c=p==='workspace'?overview():p==='crm'?crm():p==='lead'?leadView():p==='forms'?formsView():p==='catalogue'?catalogue():p==='venture'?ventureView():p==='queue'?queueView():overview();html=workspace(c)}root.innerHTML=demo()+html;attachLabels()}
function attachLabels(){document.querySelectorAll('label:not([for])').forEach((l,i)=>{let c=l.nextElementSibling;if(c?.matches('input,select,textarea')){c.id=c.id||'f-'+i;l.htmlFor=c.id}})}
function home(){return `<div class="wrap">${publicNav()}<section class="hero"><div><div class="eyebrow">business architecture · hamzury holding</div><h1>your ambition.<br>a clearer route.<br><em>put together.</em></h1><p>understand what your business needs now. choose the right support. build with specialists who work from one clear roadmap.</p><div class="actions">${button('find my next step →','form/general/new')}${button('i know what i need','form/direct/new','secondary')}</div><p class="small" style="margin-top:22px">start with your situation. you do not need to start everything at once.</p></div><div class="architecture"><div class="core"><div class="eyebrow">different expertise. one business.</div><b>yours.</b><p class="small">one plan connects the right specialists.</p></div><div class="archlist">${db.ventures.map(v=>`<a href="#form/${v.name==='bizdoc'?'compliance':v.name==='subt'?'software':v.name==='hamzury hub'?'training':v.name==='medialy'?'growth':'general'}/new?source=${encodeURIComponent(v.name+' website')}"><b>${E(v.name)}</b><span>${E(v.mandate)}</span></a>`).join('')}</div></div></section><section class="section"><div class="sectionhead"><div><div class="eyebrow">where are you today?</div><h2>begin with your situation.</h2></div><p class="small">a few relevant questions.<br>a practical next step.</p></div><div class="grid">${[['general','i’m starting or structuring a business','clarify the idea, foundation and route forward.'],['growth','i want more customers','review the offer, enquiries and sales process.'],['direct','i need a specific service','tell us what you need and when you need it.'],['software','i need better systems','find a suitable software or workflow solution.'],['compliance','i need documents or compliance help','understand the business requirement before processing.'],['training','i want to build my skills','explore a practical learning and project route.']].map(([id,t,d],i)=>`<article class="card"><span class="number">0${i+1} / discovery</span><h3>${t}</h3><p>${d}</p><button class="ghost" onclick="go('form/${id}/new')">start here →</button></article>`).join('')}</div></section><section class="section" id="expertise"><div class="sectionhead"><div><div class="eyebrow">one institution. specialist support.</div><h2>the expertise behind your roadmap.</h2></div></div><div class="grid">${db.ventures.map(v=>`<div class="card">${V.some(x=>x[0]===v.name)?`<img class="venturelogo" src="assets/${v.name==='hamzury hub'?'hub':v.name}.png" alt="${E(v.name)}">`:`<h3>${E(v.name)}</h3>`}<p>${E(v.mandate)}</p><span class="small">recommended when it serves your business.</span></div>`).join('')}</div></section><section class="section"><div class="two"><div><div class="eyebrow">your journey</div><h2>see the reason.<br>choose the work.<br>follow the progress.</h2><p>your proposal explains the priorities. your roadmap lets you choose. your project keeps requirements, updates and deliveries together.</p>${button('explore a sample client journey →','client/HH-DEMO-001/proposal')}</div><div class="card">${[['01','understand','answer the questions relevant to your situation.'],['02','choose','review a tailored recommendation and select services.'],['03','activate','confirm the scope, payment and requirements.'],['04','progress','see who is working, what is needed and what is delivered.']].map(x=>`<div class="row"><span class="small">${x[0]}</span><div><h3>${x[1]}</h3><p class="small">${x[2]}</p></div></div>`).join('')}</div></div></section>${footer()}</div>`}
function overview(){let pending=db.leads.filter(l=>l.work.length&&!l.work.every(w=>w.status==='delivered')).length;return title('holding command centre','the whole journey, connected.','one place to receive enquiries, publish recommendations and coordinate delivery.',button('+ capture an enquiry','crm/new'))+`<div class="grid four">${[[db.leads.length,'client records'],[db.forms.length,'discovery routes'],[db.ventures.length,'venture workspaces'],[pending,'active sample projects']].map(x=>`<div class="card"><span class="small">${x[1]}</span><div class="metric">${x[0]}</div></div>`).join('')}</div><div class="two" style="margin-top:22px"><div class="card"><div class="eyebrow">start here</div><h2>from a conversation to a clear next step.</h2><p>capture a whatsapp, offline, website or referral enquiry. choose a suitable discovery form. publish the proposal and roadmap separately, then activate only verified, agreed work.</p><div class="actions">${button('open client crm →','crm')}${button('edit discovery routes','forms','secondary')}</div></div><div class="card"><h2>experience both sides.</h2><p>use the holding workspace to manage the record. open the client link to see the recommendation, requirements, messages and delivered files.</p>${button('open sample client project →','client/HH-DEMO-001/proposal','secondary')}</div></div><div class="sectionhead"><h2>recent client records</h2></div>${leadTable(db.leads.slice(0,5))}${note('production boundary: these are connected browser-local workflows. live accounts, shared records, scheduled notifications, verified payment integrations and private file storage require the production backend. no whatsapp messages are sent by this experience.')}`}
function leadTable(ls){return `<div class="card tablewrap"><table><thead><tr><th>client / id</th><th>source</th><th>stage</th><th>next action</th><th></th></tr></thead><tbody>${ls.map(l=>`<tr><td><b>${E(l.name)}</b><br><span class="small">${E(l.id)}</span></td><td>${E(l.source)}<br>${E(l.venture)}</td><td>${pill(l.stage)}</td><td>${E(l.next||'review enquiry')}</td><td>${button('open →','lead/'+l.id)}</td></tr>`).join('')}</tbody></table>${ls.length?'':'<div class="empty">no matching enquiries.</div>'}</div>`}
function crm(){if(route[1]==='new')return newLead();let ls=db.leads.filter(l=>(filter==='all'||l.source===filter)&&(!query||(l.name+' '+l.contact+' '+l.id).toLowerCase().includes(query.toLowerCase())));return title('central crm','every enquiry has a next action.','source attribution follows the client from first contact to delivery.',button('+ capture enquiry','crm/new'))+`<div class="searchbar"><input aria-label="search clients" placeholder="search name, contact or client id" value="${E(query)}" oninput="query=this.value;document.getElementById('crmlist').innerHTML=leadTable(db.leads.filter(l=>(filter==='all'||l.source===filter)&&(!query||(l.name+' '+l.contact+' '+l.id).toLowerCase().includes(query.toLowerCase()))))"><select aria-label="filter source" onchange="filter=this.value;render()">${['all',...new Set(db.leads.map(l=>l.source))].map(s=>`<option ${filter===s?'selected':''}>${E(s)}</option>`).join('')}</select></div><div id="crmlist">${leadTable(ls)}</div><div class="sectionhead"><h2>pipeline</h2><span class="small">open a card to move the work through its gates.</span></div><div class="kanban">${[['discovery',['new','discovery']],['proposal',['proposal']],['roadmap & payment',['roadmap','payment']],['active work',['onboarding','active']],['delivered',['delivered']]].map(([name,stages])=>`<div class="column"><h3>${name}</h3>${ls.filter(l=>stages.includes(l.stage)).map(l=>`<article class="leadcard" onclick="go('lead/${l.id}')"><span class="small">${E(l.source)}</span><b>${E(l.name)}</b><span class="small">${E(l.next)}</span></article>`).join('')||'<p class="small">no records</p>'}</div>`).join('')}</div>`}
function newLead(){return title('capture an enquiry','start with the conversation.','record the source, choose the discovery route and keep ownership clear.')+`<form class="card" onsubmit="capture(event)"><div class="formgrid"><div><label>business or client name</label><input name="name" required></div><div><label>contact reference</label><input name="contact" placeholder="demo contact only" required></div><div><label>source</label><select name="source">${['whatsapp','offline / walk-in','holding website','bizdoc website','medialy website','subt website','hub website','affiliate','referral','other'].map(s=>`<option>${s}</option>`).join('')}</select></div><div><label>initial venture / owner</label><select name="venture"><option>holding</option>${db.ventures.map(v=>`<option>${E(v.name)}</option>`).join('')}</select></div><div><label>discovery scenario</label><select name="scenario">${db.forms.map(f=>`<option value="${f.id}">${E(f.title)}</option>`).join('')}</select></div><div><label>follow-up due</label><input name="due" type="datetime-local"></div><div class="full"><label>what did they ask for?</label><textarea name="next" required></textarea></div></div>${note('for the demonstration, use sample contacts only. the live crm will match normalized contact details and let the team review possible duplicates.') }<div class="actions"><button>create client record →</button>${button('cancel','crm','secondary')}</div></form>`}
function capture(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));let existing=db.leads.find(l=>l.contact.trim().toLowerCase()===d.contact.trim().toLowerCase());if(existing){toast('matching contact found. opening the existing record for review.');go('lead/'+existing.id);return}let l={...d,id:uid('HH'),stage:'new',created:now(),answers:{},proposal:'',proposalVersion:null,roadmapVersion:null,selected:[],paid:false,requirements:[],work:[],files:[],updates:[],events:[]};db.leads.unshift(l);event(l,'enquiry captured: '+l.source);go('lead/'+l.id)}
function formsView(){if(route[1]==='edit')return editForm(route[2]);return title('discovery studio','different situations. relevant questions.','choose, edit and publish a form without forcing every client through the same questions.',button('+ new discovery template','forms/edit/new'))+`<div class="grid">${db.forms.map(f=>`<div class="card"><div class="eyebrow">${f.qs.length} questions · ${f.published?'published snapshot':'draft template'}</div><h2>${E(f.title)}</h2><p>${E(f.intro)}</p><div class="actions">${button('edit questions','forms/edit/'+f.id,'secondary')}<button onclick="publishForm('${f.id}')">publish form</button></div>${f.published?`<div class="linkbox">${E(link('form/'+f.id+'/new'))}</div>${button('preview client form →','form/'+f.id+'/new','ghost')}`:''}</div>`).join('')}</div>`}
function editForm(id){let f=db.forms.find(x=>x.id===id)||{id:'new',title:'',intro:'',qs:[]};return title('discovery editor','ask only what this scenario needs.','publishing creates a snapshot. draft edits do not alter an already-published form.')+`<form class="card" onsubmit="storeForm(event,'${f.id}')"><label>form name</label><input name="title" value="${E(f.title)}" required><label>client introduction</label><textarea name="intro" required>${E(f.intro)}</textarea><label>questions, one per line</label><textarea name="questions" style="min-height:260px" required>${E(f.qs.map(q=>q.label+' | '+q.type+(['select','multiselect'].includes(q.type)?' | '+q.options.join('; '):'')).join('\n'))}</textarea>${note('format: question | text<br>or: question | textarea<br>or: question | select | option one; option two<br>discovery does not request identity or payment files. post-payment checklists handle those requirements.') }<div class="actions"><button>save draft</button>${button('back','forms','secondary')}</div></form>`}
function storeForm(e,id){e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),old=db.forms.find(x=>x.id===id),qs=d.questions.split('\n').filter(x=>x.trim()).map((x,i)=>{let a=x.split('|').map(s=>s.trim());return Q(old?.qs[i]?.id||'q'+i,a[0],['text','textarea','select','multiselect'].includes(a[1])?a[1]:'text',(a[2]||'').split(';').map(x=>x.trim()).filter(Boolean))});if(!qs.length){toast('add at least one question');return}if(old)Object.assign(old,{title:d.title,intro:d.intro,qs});else db.forms.push({id:uid('discovery'),...d,qs});save();go('forms');toast('discovery draft saved')}
function publishForm(id){let f=db.forms.find(x=>x.id===id);f.published={title:f.title,intro:f.intro,qs:structuredClone(f.qs),at:now()};save();render();toast('form snapshot published for this demonstration')}
function discoveryView(){let f=db.forms.find(x=>x.id===route[1]);if(!f)return notFound();let idpart=(route[2]||'new').split('?')[0],l=lead(idpart),pub=l?.discoverySnapshot||f.published||f;let key=f.id+'/'+idpart;if(currentFormKey!==key){currentFormKey=key;formStep=0;formAnswers={...(l?.answers||{}),...JSON.parse(localStorage.getItem('hh-form-'+key)||'{}')}}let q=pub.qs[formStep];if(!q)return notFound();let value=formAnswers[q.id]||'';return `<div class="clientwrap">${publicNav()}<div class="clientcover"><div class="eyebrow">${E(l?.name||'your business')} / discovery</div><h1>${E(pub.title)}</h1><p>${E(pub.intro)}</p></div><div class="two"><form class="card" onsubmit="nextAnswer(event,'${f.id}','${idpart}')"><div class="eyebrow">question ${formStep+1} of ${pub.qs.length}</div><div class="progress">${pub.qs.map((_,i)=>`<i class="${i<=formStep?'done':''}"></i>`).join('')}</div><h2>${E(q.label)}</h2><label class="small" for="answer">your answer</label>${q.type==='textarea'?`<textarea id="answer" name="answer" required>${E(value)}</textarea>`:q.type==='select'?`<select id="answer" name="answer" required><option value="">choose an option</option>${q.options.map(o=>`<option ${value===o?'selected':''}>${E(o)}</option>`).join('')}</select>`:`<input id="answer" name="answer" value="${E(value)}" required>`}${!l&&formStep===pub.qs.length-1?'<label for="returncontact">your contact reference (sample only)</label><input id="returncontact" name="returncontact" required placeholder="sample email or whatsapp reference">':''}<div class="actions">${formStep?'<button class="secondary" type="button" onclick="formStep--;render()">back</button>':''}<button>${formStep===pub.qs.length-1?'submit discovery →':'continue →'}</button></div><p class="small" style="margin-top:20px">your answers are saved in this browser as you continue.</p></form><div class="card"><h3>what happens next?</h3><p>we review your answers, identify what needs checking and prepare a recommendation. you choose the work after reviewing its scope and cost.</p>${note('design demonstration. do not enter sensitive information. submitting creates or updates a sample record in this browser only.')}</div></div>${footer()}</div>`}
function nextAnswer(e,fid,id){e.preventDefault();let f=db.forms.find(x=>x.id===fid),pub=lead(id)?.discoverySnapshot||f.published||f,q=pub.qs[formStep];let submitted=new FormData(e.target);formAnswers[q.id]=submitted.get('answer');if(submitted.get('returncontact'))formAnswers._contact=submitted.get('returncontact');localStorage.setItem('hh-form-'+currentFormKey,JSON.stringify(formAnswers));if(formStep<pub.qs.length-1){formStep++;render();return}let l=lead(id)||db.leads.find(x=>formAnswers._contact&&x.contact.toLowerCase()===formAnswers._contact.trim().toLowerCase());if(!l){let src=new URLSearchParams(location.hash.split('?')[1]||'').get('source')||'holding website';l={id:uid('HH'),name:formAnswers.business||formAnswers[pub.qs[0].id]||'new discovery',contact:formAnswers._contact||'website demo '+uid('ref'),source:src,venture:db.ventures.find(v=>src===v.name+' website')?.name||'holding',scenario:fid,created:now(),proposal:'',proposalVersion:null,roadmapVersion:null,selected:[],paid:false,requirements:[],work:[],files:[],updates:[],events:[]};db.leads.unshift(l)}l.answers={...formAnswers};l.stage='discovery';l.next='team reviews the discovery and prepares a proposal';event(l,'discovery submitted: '+f.title);root.innerHTML=demo()+`<div class="clientwrap">${publicNav()}<div class="clientcover"><div class="eyebrow">discovery received</div><h1>your next step is with our team.</h1><p>we will review what you shared before recommending services. your reference is <b>${E(l.id)}</b>.</p>${button('preview your client page →','client/'+l.id+'/proposal')}${note('the demonstration crm now contains these answers. use workspace preview to continue as the team.')}</div>${footer()}</div>`}
function leadView(){let l=lead(route[1]);if(!l)return notFound();let tab=route[2]||'overview';let tabs=['overview','discovery','proposal','roadmap','payment','requirements','delivery','updates'];return title(E(l.id),E(l.name),`${E(l.source)} · owner: ${E(l.venture)} · ${E(l.stage)}`,button('open client view ↗','client/'+l.id+'/proposal','secondary'))+`<div class="tabs">${tabs.map(t=>`<button class="${t===tab?'active':''}" onclick="go('lead/${l.id}/${t}')">${t}</button>`).join('')}</div>`+leadPanel(l,tab)}
function leadPanel(l,t){if(t==='overview')return `<div class="two"><div class="card"><h2>next action & ownership</h2><form onsubmit="updateLead(event,'${l.id}')"><label>responsible venture</label><select name="venture"><option>holding</option>${db.ventures.map(v=>`<option ${v.name===l.venture?'selected':''}>${E(v.name)}</option>`).join('')}</select><label>next action</label><textarea name="next" required>${E(l.next)}</textarea><label>due date</label><input name="due" type="datetime-local" value="${E(l.due)}"><div class="actions"><button>save next action</button></div></form></div><div class="card"><h2>record history</h2>${l.events.slice(0,12).map(e=>`<div class="statusline"><span class="small">${displayDate(e.at)}</span><p>${E(e.text)}</p></div>`).join('')}</div></div>`;
if(t==='discovery')return `<div class="two"><div class="card"><h2>choose the right discovery.</h2><form onsubmit="setDiscovery(event,'${l.id}')"><label>scenario</label><select name="scenario">${db.forms.map(f=>`<option value="${f.id}" ${l.scenario===f.id?'selected':''}>${E(f.title)}</option>`).join('')}</select><div class="actions"><button>prepare discovery link</button></div></form><div class="linkbox">${E(link('form/'+l.scenario+'/'+l.id))}</div>${button('preview client questions →','form/'+l.scenario+'/'+l.id,'secondary')}${note('whatsapp draft: hello, please use this short discovery link so we can understand your situation and recommend the next step. no message is sent automatically.')}</div><div class="card"><h2>answers received</h2>${Object.entries(l.answers).map(([k,v])=>`<div class="row"><div><span class="small">${E((db.forms.find(f=>f.id===l.scenario)?.published?.qs||db.forms.find(f=>f.id===l.scenario)?.qs||[]).find(q=>q.id===k)?.label||k)}</span><p>${E(v)}</p></div></div>`).join('')||'<p>waiting for client responses.</p>'}</div></div>`;
if(t==='proposal')return `<div class="card"><h2>explain the recommendation.</h2><form onsubmit="saveProposal(event,'${l.id}')"><label>business assessment and recommended next step</label><textarea name="proposal" style="min-height:170px" required>${E(l.proposal)}</textarea><div class="actions"><button>save proposal draft</button></div></form>${note('separate confirmed facts from assumptions. check the need before recommending a purchase. publishing freezes the client-facing version until you publish a revision.')}<button onclick="publishProposalFor('${l.id}')">publish proposal →</button>${l.proposalVersion?`<div class="linkbox">${E(link('client/'+l.id+'/proposal'))}</div><p class="small">version ${l.proposalVersion.version} · ${displayDate(l.proposalVersion.at)}</p>`:''}</div>`;
if(t==='roadmap')return `<div class="card"><h2>curate this client’s roadmap.</h2><p>select relevant services from the venture catalogue. all four package stages can contribute to the plan.</p><form onsubmit="saveRoadmap(event,'${l.id}')">${['minimum','standard','premium','scale & growth'].map((tier,n)=>`<details ${n===0?'open':''}><summary>${tier}</summary>${db.services.filter(s=>s.level===n).map(s=>`<div class="checkrow"><input id="s-${s.id}" type="checkbox" name="service" value="${s.id}" ${l.selected.includes(s.id)?'checked':''}><label for="s-${s.id}">${tag(s.v)} <b>${E(s.title)}</b><br><span class="small">${s.price!==''?'₦'+Number(s.price).toLocaleString():'quote required'} · ${E(s.deliver)}</span></label></div>`).join('')}</details>`).join('')}<div class="actions"><button>save roadmap draft</button><button type="button" class="secondary" onclick="publishRoadmapFor('${l.id}')">publish saved roadmap →</button></div></form>${l.roadmapVersion?`<div class="linkbox">${E(link('client/'+l.id+'/roadmap'))}</div><p class="small">published version ${l.roadmapVersion.version} · prices are snapshots of the catalogue at publication.</p>`:''}</div>`;
if(t==='payment')return `<div class="two"><div class="card"><h2>payment verification</h2>${pill(l.paid?'verified sample payment':'not verified')}<p>quotation acceptance and payment evidence are separate records. a receipt alone does not activate work.</p><form onsubmit="verifyPayment(event,'${l.id}')"><label>amount verified (₦)</label><input name="amount" type="number" min="1" step="0.01" value="${l.payment?.amount||''}" required><label>transaction reference</label><input name="ref" value="${E(l.payment?.ref||'')}" required><label class="checkrow"><input type="checkbox" required> sample scope and quotation acceptance checked</label><label class="checkrow"><input type="checkbox" required> sample transaction independently checked by finance</label><div class="actions"><button ${!l.roadmapVersion?'disabled':''}>confirm sample payment & route work</button></div></form>${note('publish the roadmap first. this is an internal verification simulation, not a connection to a bank or payment provider. no money is collected.')}</div><div class="card"><h2>activated work</h2>${l.work.map(w=>`<div class="row"><div>${tag(w.venture)}<h3>${E(w.title)}</h3></div>${pill(w.status)}</div>`).join('')||'<p>no active work. verification creates venture work orders once, without duplicates.</p>'}</div></div>`;
if(t==='requirements')return requirementsEditor(l);
if(t==='delivery')return deliveryEditor(l);
return `<div class="two"><div class="card"><h2>send a project update.</h2><form onsubmit="addUpdate(event,'${l.id}')"><label>update for the client</label><textarea name="message" required placeholder="completed, happening now, any blocker and next update"></textarea><label>who needs to act next?</label><select name="waiting"><option>our team</option><option>you</option><option>external process</option></select><label>client’s next action</label><textarea name="next" required></textarea><label>action due</label><input name="due" type="datetime-local"><div class="actions"><button>publish update to client portal</button></div></form></div><div class="card"><h2>published updates</h2>${l.updates.map(u=>`<div class="statusline"><span class="small">${displayDate(u.at)} · waiting for ${E(u.waiting)}</span><p>${E(u.message)}</p><b class="small">next: ${E(u.next)}</b></div>`).join('')||'<p>no updates published yet.</p>'}</div></div>`}
function updateLead(e,id){e.preventDefault();let l=lead(id);Object.assign(l,Object.fromEntries(new FormData(e.target)));event(l,'next action and owner updated');toast('next action saved')}
function setDiscovery(e,id){e.preventDefault();let l=lead(id);l.scenario=new FormData(e.target).get('scenario');let f=db.forms.find(x=>x.id===l.scenario);if(!f.published)f.published={title:f.title,intro:f.intro,qs:structuredClone(f.qs),at:now()};l.discoverySnapshot=structuredClone(f.published);l.stage='discovery';event(l,'discovery link prepared: '+f.title);render()}
function saveProposal(e,id){e.preventDefault();let l=lead(id);l.proposal=new FormData(e.target).get('proposal');event(l,'proposal draft saved');toast('draft saved. publish to update the client view.')}
function publishProposalFor(id){let l=lead(id);if(!l.proposal.trim()){toast('save the proposal draft first');return}l.proposalVersion={text:l.proposal,version:(l.proposalVersion?.version||0)+1,at:now()};l.stage='proposal';event(l,'proposal published, version '+l.proposalVersion.version);render()}
function saveRoadmap(e,id){e.preventDefault();let l=lead(id);l.selected=new FormData(e.target).getAll('service');event(l,'roadmap draft saved');toast('roadmap draft saved. publish when ready.')}
function publishRoadmapFor(id){let l=lead(id);if(!l.proposalVersion){toast('publish the proposal first');return}if(!l.selected.length){toast('save at least one service first');return}l.roadmapVersion={services:structuredClone(db.services.filter(s=>l.selected.includes(s.id))),version:(l.roadmapVersion?.version||0)+1,at:now()};l.clientSelected=l.roadmapVersion.services.map(s=>s.id);l.stage='roadmap';l.next='client reviews roadmap and selects services';event(l,'roadmap published, version '+l.roadmapVersion.version);render()}
function verifyPayment(e,id){e.preventDefault();let l=lead(id),d=Object.fromEntries(new FormData(e.target));if(!l.roadmapVersion)return;let services=l.roadmapVersion.services.filter(s=>(l.clientSelected||l.selected).includes(s.id));if(!services.length){toast('client selection is empty');return}l.paid=true;l.payment={...d,at:now(),simulation:true};services.forEach(s=>{if(!l.work.some(w=>w.serviceId===s.id))l.work.push({id:uid('work'),serviceId:s.id,venture:s.v,title:s.title,status:'ready',owner:'venture operations lead',due:'',standard:s.deliver,evidence:''});if(!l.requirements.some(r=>r.serviceId===s.id))l.requirements.push({id:uid('req'),serviceId:s.id,title:s.req,venture:s.v,status:'needed',answer:'',due:''})});l.stage='onboarding';l.next='client supplies the service-specific requirements';event(l,'sample payment verified. work routed to responsible ventures.');render()}
function requirementsEditor(l){return `<div class="card"><h2>the checklist follows the purchased work.</h2><p>edit requests, due dates and status for this client. only this order’s checklist changes.</p>${l.requirements.map(r=>`<form onsubmit="saveRequirement(event,'${l.id}','${r.id}')"><div class="row"><div>${tag(r.venture)} ${pill(r.status)}</div></div><label>requirement request</label><textarea name="title" required>${E(r.title)}</textarea><div class="formgrid"><div><label>status</label><select name="status">${['needed','submitted','accepted','changes requested'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div><label>due</label><input type="datetime-local" name="due" value="${E(r.due)}"></div></div><p class="small">client response: ${E(r.answer||'not yet supplied')}</p><div class="actions"><button class="mini secondary">save requirement</button></div></form>`).join('')||'<p>requirements are generated after sample payment verification. you can also add a relevant request below.</p>'}<form onsubmit="newRequirement(event,'${l.id}')"><label>add a requirement</label><textarea name="title" required></textarea><label>venture</label><select name="venture">${db.ventures.map(v=>`<option>${E(v.name)}</option>`).join('')}</select><div class="actions"><button>add to client checklist</button></div></form></div>`}
function saveRequirement(e,id,rid){e.preventDefault();let l=lead(id),r=l.requirements.find(r=>r.id===rid);Object.assign(r,Object.fromEntries(new FormData(e.target)));event(l,'requirement checklist updated');toast('requirement saved')}
function newRequirement(e,id){e.preventDefault();let l=lead(id);l.requirements.push({...Object.fromEntries(new FormData(e.target)),id:uid('req'),status:'needed',answer:'',due:''});event(l,'requirement added');render()}
function deliveryEditor(l){return `<div class="two"><div class="card"><h2>work & quality review</h2>${l.work.map(w=>`<form onsubmit="updateWork(event,'${l.id}','${w.id}')"><div class="row"><div>${tag(w.venture)}<h3>${E(w.title)}</h3></div></div><p class="small">standard: ${E(w.standard)}</p><label>responsible person / role</label><input name="owner" value="${E(w.owner)}" required><label>delivery due</label><input type="datetime-local" name="due" value="${E(w.due)}"><label>status</label><select name="status">${['ready','in progress','blocked','under review','changes requested','approved','delivered'].map(s=>`<option ${s===w.status?'selected':''}>${s}</option>`).join('')}</select><label>completion evidence / blocker</label><textarea name="evidence">${E(w.evidence)}</textarea><div class="actions"><button class="mini">save work update</button></div></form>`).join('')||'<p>work is created after the payment gate.</p>'}</div><div class="card"><h2>upload & release documents</h2><form onsubmit="uploadDelivery(event,'${l.id}')"><label>document title</label><input name="title" required><label>related work</label><select name="workId" required><option value="">choose work</option>${l.work.map(w=>`<option value="${w.id}">${E(w.title)}</option>`).join('')}</select><label>sample document</label><input type="file" name="file" required><label>release</label><select name="release"><option value="draft">internal draft</option><option value="review">client review</option><option value="final">final delivery</option></select><div class="actions"><button ${l.work.length?'':'disabled'}>store sample document</button></div></form>${note('demo files are stored locally in this browser, up to 2 mb each. use test files only. final release requires approved work. this does not upload files to a shared client server.')}<h3>document register</h3>${l.files.map(f=>`<div class="row"><div><b>${E(f.title)}</b><br><span class="small">${E(f.release)} · ${E(f.name)}</span></div><button class="mini secondary" onclick="downloadFile('${f.id}')">download</button></div>`).join('')||'<p class="small">no files stored yet.</p>'}</div></div>`}
function updateWork(e,id,wid){e.preventDefault();let l=lead(id),w=l.work.find(x=>x.id===wid),d=Object.fromEntries(new FormData(e.target));if(['under review','approved','delivered'].includes(d.status)&&!d.evidence.trim()){toast('record evidence before submission or approval');return}if(d.status==='delivered'&&!l.files.some(f=>f.workId===wid&&f.release==='final')){toast('release an approved final document before marking delivered');return}Object.assign(w,d);l.stage=l.work.every(w=>w.status==='delivered')?'delivered':'active';event(l,'work update: '+w.title+' / '+w.status);toast('work updated')}
const filesDB=new Promise((res,rej)=>{let r=indexedDB.open('hh-demo-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
async function uploadDelivery(e,id){e.preventDefault();let form=e.target,d=new FormData(form),f=d.get('file'),l=lead(id),w=l.work.find(w=>w.id===d.get('workId'));if(!w)return;if(f.size>2*1024*1024){toast('use a sample file smaller than 2 mb');return}if(d.get('release')==='final'&&!['approved','delivered'].includes(w.status)){toast('approve the work before releasing a final file');return}let fid=uid('file');try{let idb=await filesDB;await new Promise((res,rej)=>{let tx=idb.transaction('files','readwrite');tx.objectStore('files').put(f,fid);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});l.files.push({id:fid,name:f.name,title:d.get('title'),workId:w.id,release:d.get('release'),at:now()});event(l,'document stored: '+d.get('title')+' / '+d.get('release'));render();toast('sample document stored locally')}catch{toast('file storage unavailable in this browser')}}
async function downloadFile(id){try{let idb=await filesDB;let file=await new Promise((res,rej)=>{let r=idb.transaction('files').objectStore('files').get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});if(!file){toast('this file exists only in the browser where it was uploaded');return}let a=document.createElement('a');a.href=URL.createObjectURL(file);a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch{toast('unable to open the browser-local file')}}
function addUpdate(e,id){e.preventDefault();let l=lead(id),d=Object.fromEntries(new FormData(e.target));l.updates.unshift({...d,at:now()});l.next=d.next;l.due=d.due;event(l,'client update published');render()}
function clientNav(l,t){let tabs=[['proposal','your proposal'],['roadmap','your roadmap'],['payment','activation'],['requirements','requirements'],['status','my project']];return `<div class="clientwrap">${publicNav()}<div class="clientcover"><div class="eyebrow">your business / ${E(l.id)}</div><h1>${E(l.name)}</h1><p>your journey. a clear roadmap.</p></div><div class="tabs">${tabs.map(([s,n])=>`<button class="${s===t?'active':''}" onclick="go('client/${l.id}/${s}')">${n}</button>`).join('')}</div>`}
function clientView(){let l=lead(route[1]);if(!l)return notFound();let t=route[2]||'proposal',out='';if(t==='proposal')out=`<div class="two"><div class="card"><div class="eyebrow">a recommendation for your next step</div><h2>start with what matters now.</h2><p style="white-space:pre-wrap">${E(l.proposalVersion?.text||'your team is reviewing the discovery. your proposal will appear here after it is published.')}</p>${l.proposalVersion?button('continue to my roadmap →','client/'+l.id+'/roadmap'):button('complete your discovery →','form/'+l.scenario+'/'+l.id)}<p class="small" style="margin-top:16px">${l.proposalVersion?'published version '+l.proposalVersion.version+' · '+displayDate(l.proposalVersion.at):'next action: complete discovery or wait for team review.'}</p></div><div class="card"><h2>you choose the pace.</h2><p>we explain the reason, scope and requirements before you commit. start with relevant services and return to the next stage when you are ready.</p>${note('this demonstration uses a browser-local client record. an id identifies the client; production access must also verify their identity.')}</div></div>`;
else if(t==='roadmap'){let sv=l.roadmapVersion?.services||[];out=sv.length?`<h2>your priorities, in stages.</h2><div class="stagegrid">${['minimum','standard','premium','scale & growth'].map((n,i)=>`<button class="stage ${clientTier===i?'active':''}" onclick="clientTier=${i};render()"><span>stage 0${i+1}</span><strong>${n}</strong><span>${sv.filter(s=>s.level===i).length} recommended services</span></button>`).join('')}</div><div class="grid" style="margin-top:20px">${sv.filter(s=>s.level===clientTier).map(s=>`<article class="card">${tag(s.v)}<h2>${E(s.title)}</h2><p>${E(s.scope)}</p><details><summary>scope, requirements & delivery</summary><p><b>deliverables:</b> ${E(s.deliver)}</p><p><b>requirements:</b> ${E(s.req)}</p><p><b>delivery estimate:</b> ${s.days?E(s.days)+' working days after agreed requirements':'to confirm in quotation'}</p></details><div class="row"><span>${s.price!==''?'₦'+Number(s.price).toLocaleString():'quote required'}</span><button class="mini ${(l.clientSelected||[]).includes(s.id)?'secondary':''}" onclick="clientChoose('${l.id}','${s.id}')">${(l.clientSelected||[]).includes(s.id)?'remove':'select +'}</button></div></article>`).join('')||'<div class="card"><p>no work is recommended at this stage yet. your team can add a relevant next stage later.</p></div>'}</div><div class="selection"><div><b>${(l.clientSelected||[]).length} services selected</b><p class="small">${clientTotal(l)}</p></div>${button('activate my selected services →','client/'+l.id+'/payment')}</div>`:`<div class="card"><h2>your roadmap is being prepared.</h2><p>your team will publish selected services after reviewing the recommendation.</p></div>`;}
else if(t==='payment')out=`<div class="two"><div class="card"><h2>review before activation.</h2>${(l.roadmapVersion?.services||[]).filter(s=>(l.clientSelected||[]).includes(s.id)).map(s=>`<div class="row"><div>${tag(s.v)}<h3>${E(s.title)}</h3></div><span>${s.price!==''?'₦'+Number(s.price).toLocaleString():'unpriced'}</span></div>`).join('')||'<p>select services from your roadmap first.</p>'}<p>${clientTotal(l)}</p>${pill(l.paid?'sample payment verified':'awaiting agreed quote and verification')}<div class="actions"><button onclick="requestQuote('${l.id}')">request final quotation</button></div>${note('no money is collected here. the live checkout must present the accepted scope, itemized costs and terms before payment. finance verifies the actual transaction before activation.')}</div><div class="card"><h2>what happens after payment?</h2><p>your purchased services activate. supply the relevant requirements once, then follow the work and download approved deliveries.</p>${l.paid?button('complete my requirements →','client/'+l.id+'/requirements'):button('view my project status','client/'+l.id+'/status','secondary')}</div></div>`;
else if(t==='requirements')out=`<div class="card"><h2>what we need from you.</h2><p>only provide the information requested for your selected services.</p>${l.requirements.map(r=>`<form onsubmit="respondRequirement(event,'${l.id}','${r.id}')"><div class="row"><div>${tag(r.venture)}<h3>${E(r.title)}</h3><span class="small">due: ${displayDate(r.due)}</span></div>${pill(r.status)}</div><label>your response</label><textarea name="answer" required>${E(r.answer)}</textarea><label>sample supporting file, optional (up to 2 mb)</label><input type="file" name="supporting"><div class="actions"><button class="mini secondary">submit response</button></div></form>`).join('')||'<p>no requirements have been requested yet. your team will activate the relevant checklist after payment verification.</p>'}${note('use sample text only in this demonstration. secure client requirement uploads are part of the production implementation.')}</div>`;
else out=`<div class="two"><div><div class="card"><h2>your active services</h2>${l.work.map(w=>`<div class="row"><div>${tag(w.venture)}<h3>${E(w.title)}</h3><span class="small">expected delivery: ${displayDate(w.due)}</span><p class="small">${E(w.evidence||'the responsible team will publish the next update.')}</p></div>${pill(w.status)}</div>`).join('')||'<p>no active work yet. review your roadmap and quotation to begin.</p>'}</div><div class="card" style="margin-top:20px"><h2>your documents</h2>${l.files.filter(f=>['review','final'].includes(f.release)).map(f=>`<div class="row"><div><h3>${E(f.title)}</h3><span class="small">${f.release==='final'?'delivered':'for your review'} · ${displayDate(f.at)}</span></div><button class="mini" onclick="downloadFile('${f.id}')">download</button></div>`).join('')||'<p>released drafts and final deliveries will appear here.</p>'}</div><div class="card" style="margin-top:20px"><h2>project updates</h2>${l.updates.map(u=>`<div class="statusline"><span class="small">${displayDate(u.at)} · waiting for ${E(u.waiting)}</span><p>${E(u.message)}</p></div>`).join('')||'<p>no update published yet.</p>'}</div></div><div><div class="card"><div class="eyebrow">your next step</div><h2>${E(l.next||'review your proposal')}</h2><p>due: ${displayDate(l.due)}</p>${button('open requirements →','client/'+l.id+'/requirements','secondary')}${note('we keep you informed. your project record shows who needs to act and what is expected next.')}</div><div class="card" style="margin-top:20px"><h2>feedback or correction?</h2><form onsubmit="feedback(event,'${l.id}')"><label>tell your team what needs attention</label><textarea name="message" required></textarea><div class="actions"><button>submit feedback</button></div></form></div><div class="card" style="margin-top:20px"><div class="eyebrow">continue your roadmap</div><h2>build the next stage when you are ready.</h2><p>review the next useful service with your team. completed work should be checked before anything is proposed again.</p>${button('review my roadmap','client/'+l.id+'/roadmap','secondary')}</div></div></div>`;
return clientNav(l,t)+out+footer()+'</div>'}
function clientTotal(l){let s=(l.roadmapVersion?.services||[]).filter(s=>(l.clientSelected||[]).includes(s.id));if(!s.length)return 'no services selected.';return s.some(s=>s.price==='')?'total pending an approved quotation. no unconfirmed prices are included.':'selected catalogue total: ₦'+s.reduce((n,s)=>n+Number(s.price),0).toLocaleString()+'. final scope, terms and external fees require confirmation.'}
function clientChoose(id,sid){let l=lead(id);if(l.paid){toast('this order is activated. ask your team to quote any scope changes separately.');return}let a=l.clientSelected||[];l.clientSelected=a.includes(sid)?a.filter(x=>x!==sid):[...a,sid];save();render()}
function requestQuote(id){let l=lead(id);if(!(l.clientSelected||[]).length){toast('select at least one service');return}l.stage='payment';l.next='team prepares the final quotation for selected services';event(l,'client requested a formal quotation');toast('quotation request recorded in the sample crm')}
async function respondRequirement(e,id,rid){e.preventDefault();let l=lead(id),r=l.requirements.find(r=>r.id===rid),d=new FormData(e.target),f=d.get('supporting');if(f&&f.size){if(f.size>2*1024*1024){toast('use a sample file smaller than 2 mb');return}try{let fid=uid('requirement-file'),idb=await filesDB;await new Promise((resolve,reject)=>{let tx=idb.transaction('files','readwrite');tx.objectStore('files').put(f,fid);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});l.files.push({id:fid,name:f.name,title:'requirement: '+r.title,requirementId:rid,release:'requirement',at:now()})}catch{toast('local file storage unavailable. the response was not submitted.');return}}r.answer=d.get('answer');r.status='submitted';event(l,'client submitted a requirement response');render();toast('response submitted for team review')}
function feedback(e,id){e.preventDefault();let l=lead(id);event(l,'client feedback: '+new FormData(e.target).get('message'));toast('feedback recorded for the team');e.target.reset()}
function access(){return `<div class="clientwrap">${publicNav()}<div class="clientcover"><div class="eyebrow">return to your journey</div><h1>your business.<br>your next step.</h1></div><div class="two"><form class="card" onsubmit="event.preventDefault();const l=lead(this.elements.clientid.value.trim());if(!l){toast('use a client id from this browser’s sample crm');return}go('client/'+l.id+'/status')"><h2>open your sample project.</h2><label>client id</label><input name="clientid" placeholder="HH-DEMO-001" required><div class="actions"><button>continue →</button></div>${note('sample id: HH-DEMO-001. this is a record lookup demonstration, not secure authentication. live clients need verified access.')}</form><div class="card"><h2>have a proposal link?</h2><p>open the link your team shared. it takes you directly to the published recommendation and your next action.</p>${button('open sample proposal →','client/HH-DEMO-001/proposal','secondary')}</div></div>${footer()}</div>`}
function catalogue(){if(route[1]==='edit')return serviceEditor(route[2]);return title('industry shelves / service records','one catalogue. specialist contributions.','services can appear in several industry roadmaps without being rebuilt each time.',button('+ add service','catalogue/edit/new'))+note('interior design & home finishing is the initial demonstration shelf. minimum includes your bizdoc, medialy and subt examples. additional offers are proposed standards for review. prices remain blank until entered by your team.')+`<div class="grid">${db.services.map(s=>`<div class="card">${tag(s.v)}<span class="small"> / ${['minimum','standard','premium','scale & growth'][s.level]}</span><h3>${E(s.title)}</h3><p class="small">${E(s.deliver)}</p><p class="small">${s.price!==''?'₦'+Number(s.price).toLocaleString():'price not confirmed'} · ${s.days?E(s.days)+' working days':'timing to confirm'}</p>${button('edit catalogue service','catalogue/edit/'+s.id,'secondary mini')}</div>`).join('')}</div>`}
function serviceEditor(id){let s=db.services.find(s=>s.id===id)||{id:'new',v:'bizdoc',level:0,title:'',scope:'',deliver:'',req:'',price:'',days:'',industry:'interior design & home finishing'};return title('catalogue editor','define the offer before publishing.','roadmaps keep their published snapshot when catalogue drafts change.')+`<form class="card" onsubmit="saveService(event,'${s.id}')"><div class="formgrid"><div><label>venture</label><select name="v">${db.ventures.map(v=>`<option ${s.v===v.name?'selected':''}>${E(v.name)}</option>`).join('')}</select></div><div><label>package stage</label><select name="level">${['minimum','standard','premium','scale & growth'].map((n,i)=>`<option value="${i}" ${s.level===i?'selected':''}>${n}</option>`).join('')}</select></div><div class="full"><label>service title</label><input name="title" value="${E(s.title)}" required></div><div class="full"><label>industry tags</label><input name="industry" value="${E(s.industry||'interior design & home finishing')}" required></div><div class="full"><label>why it matters</label><textarea name="scope" required>${E(s.scope)}</textarea></div><div class="full"><label>deliverables and acceptance standard</label><textarea name="deliver" required>${E(s.deliver)}</textarea></div><div class="full"><label>client requirements</label><textarea name="req" required>${E(s.req)}</textarea></div><div><label>approved price (₦), leave blank if unconfirmed</label><input type="number" name="price" min="0" step="0.01" value="${E(s.price)}"></div><div><label>estimated working days after requirements</label><input type="number" name="days" min="1" value="${E(s.days)}"></div></div><div class="actions"><button>save service draft</button>${button('cancel','catalogue','secondary')}</div></form>`}
function saveService(e,id){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.level=Number(d.level);let s=db.services.find(s=>s.id===id);if(s)Object.assign(s,d);else db.services.push({...d,id:uid('service'),approved:false});save();go('catalogue');toast('catalogue draft saved. existing published roadmaps remain unchanged.')}
function ventureView(){if(route[1]==='new')return title('venture administration','add a specialist venture.','configure a new workspace, service owner and reporting responsibility.')+`<form class="card" onsubmit="createVenture(event)"><label>venture name</label><input name="name" required><label>mandate</label><textarea name="mandate" required></textarea><label>ceo / accountable role</label><input name="ceo" required><label>identity colour</label><input name="color" type="color" value="#3b241a"><div class="actions"><button>create venture workspace</button></div></form>`;let current=decodeURIComponent(route[1]||db.ventures[0].name),v=db.ventures.find(v=>v.name===current)||db.ventures[0];let ws=db.leads.flatMap(l=>l.work.filter(w=>w.venture===v.name).map(w=>({l,w})));return title('venture workspaces','independent execution. shared standards.','each venture owns its targets, people and delivery. the holding sees the connected results.',button('+ new venture','venture/new'))+`<div class="tabs">${db.ventures.map(x=>`<button class="${x.name===v.name?'active':''}" onclick="go('venture/${encodeURIComponent(x.name)}')">${E(x.name)}</button>`).join('')}</div><div class="two"><div class="card">${tag(v.name)}<h2>${E(v.mandate)}</h2><form onsubmit="setTarget(event,${db.ventures.indexOf(v)})"><label>ceo / accountable role</label><input name="ceo" value="${E(v.ceo)}" required><label>monthly target and weekly priorities</label><textarea name="target" required>${E(v.target)}</textarea><div class="actions"><button>save venture target</button></div></form></div><div class="card"><h2>routed work</h2>${ws.map(({l,w})=>`<div class="row"><div><h3>${E(w.title)}</h3><span class="small">${E(l.name)} · ${E(w.owner)}<br>${E(w.status)} · due ${displayDate(w.due)}</span></div>${button('work →','lead/'+l.id+'/delivery','secondary mini')}</div>`).join('')||'<p>work appears here after a client order is activated and routed to this venture.</p>'}</div></div><div class="card" style="margin-top:20px"><h2>venture crm & daily work</h2>${leadTable(db.leads.filter(l=>l.venture===v.name||l.work.some(w=>w.venture===v.name)))}<p class="small">production permissions will restrict access by venture and assignment. this workspace is a role preview, not a live team login.</p><a class="button secondary" href="operations.html">open calendar, daily tasks, reports & standards →</a></div>`}
function createVenture(e){e.preventDefault();let v=Object.fromEntries(new FormData(e.target));v.name=v.name.trim().toLowerCase();if(db.ventures.some(x=>x.name===v.name)){toast('a venture with this name already exists');return}db.ventures.push({...v,target:'not set'});save();go('venture/'+encodeURIComponent(v.name))}
function setTarget(e,index){e.preventDefault();Object.assign(db.ventures[index],Object.fromEntries(new FormData(e.target)));save();toast('venture target saved')}
function queueView(){let items=[];db.leads.forEach(l=>{if(l.due&&new Date(l.due)<new Date())items.push({l,text:l.next,due:l.due,type:'next action overdue'});if(l.work.length&&!['delivered'].includes(l.stage)){let last=l.updates[0]?.at||l.payment?.at||l.created;if(Date.now()-new Date(last)>48*3600000)items.push({l,text:'publish a client update',due:last,type:'48-hour update overdue'})}l.requirements.filter(r=>r.status!=='accepted'&&r.due&&new Date(r.due)<new Date()).forEach(r=>items.push({l,text:r.title,due:r.due,type:'requirement overdue'}));l.work.filter(w=>w.status!=='delivered'&&w.due&&new Date(w.due)<new Date()).forEach(w=>items.push({l,text:w.title,due:w.due,type:'venture delivery overdue'}))});return title('action queue','know who needs to move next.','client requests, work deadlines and the 48-hour update standard in one place.')+`<div class="card">${items.map(i=>`<div class="row"><div>${pill(i.type)}<h3 style="margin-top:10px">${E(i.l.name)}: ${E(i.text)}</h3><span class="small">${displayDate(i.due)}</span></div>${button('review →','lead/'+i.l.id)}</div>`).join('')||'<div class="empty">no overdue sample items. set due dates in a client record to test this queue.</div>'}</div>${note('this queue calculates when the page opens. production reminders must run on a server so the team is alerted even when the site is closed.')}`}
function notFound(){return `<div class="clientwrap">${publicNav()}<div class="empty"><h2>this record is not available in this browser.</h2><p>demonstration records are local to the browser where they were created. use the seeded sample to explore.</p>${button('open the sample journey','client/HH-DEMO-001/proposal')}</div></div>`}
if(!db.formInitialized){db.forms.forEach(f=>{if(!f.published)f.published={title:f.title,intro:f.intro,qs:structuredClone(f.qs),at:now()}});db.formInitialized=true;save()}
// Seed an openly labelled sample publication for a useful first visit, never a real order.
if(!db.sampleInitialized){let l=lead('HH-DEMO-001');l.proposalVersion={text:l.proposal,version:1,at:now()};l.roadmapVersion={services:structuredClone(db.services.filter(s=>['b1','m1','s1','b2','m2','s2','b3','m3','s3','b4','m4','s4'].includes(s.id))),version:1,at:now()};l.clientSelected=['b1','m1','s1'];l.stage='roadmap';db.sampleInitialized=true;save()}
window.addEventListener('hashchange',()=>{render();if(location.hash==='#home/ventures')document.getElementById('expertise')?.scrollIntoView();else window.scrollTo(0,0)});render();
